import{ax as a,A as t,aQ as p,z as i}from"./chunks/framework.BWRXlwpK.js";const l="/assets/image.rbFzJFJS.png",o="/assets/image-1.cXv0BNx3.png",v=JSON.parse('{"title":"与webpack对比","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/vite/compare.md","filePath":"webpack/vite/compare.md","lastUpdated":1788144574000}'),c={name:"webpack/vite/compare.md"};function r(s,e,n,b,d,k){return i(),t("div",null,e[0]||(e[0]=[p('<h1 id="与webpack对比" tabindex="-1">与webpack对比 <a class="header-anchor" href="#与webpack对比" aria-label="Permalink to &quot;与webpack对比&quot;">​</a></h1><h2 id="webpack原理图" tabindex="-1">webpack原理图 <a class="header-anchor" href="#webpack原理图" aria-label="Permalink to &quot;webpack原理图&quot;">​</a></h2><blockquote><p>模块在webpack进行打包形成最终打包后的结果bundle，随后返回一个开发环境的路径</p></blockquote><p><img src="'+l+'" alt="alt text"></p><p>缺点：</p><ul><li>1.当项目比较大时依赖，依赖的包和第三方库会非常多，这样打包的速度会非常的面</li><li>2.热替换十分繁琐，当改动一个模块后相关模块也需要重新打包，将重新打完的包发送到devServer服务器</li></ul><h2 id="vite原理" tabindex="-1">vite原理 <a class="header-anchor" href="#vite原理" aria-label="Permalink to &quot;vite原理&quot;">​</a></h2><blockquote><p>vite没有打包过程，直接启动开发服务器devServer，它是用koa直接启动因此速度非常快</p></blockquote><ul><li>1.即便项目使用的包和第三方库很多，但由于vite没有打包过程而是直接启动服务器，因此它还是会很快启动</li><li>2.当访问页面时会直接返回index.html文件，而在这个文件中入口js使用的是module的方式引入，因此这个入口js文件不需要被编译</li><li>3.在使用到其他模块时，使用到那个编译那个，编译后返回页面</li><li>4.在编译.vue文件时会将文件内容编译成纯js，这得益于包：【@vue/compiler-sfc】单文件组件编译器</li></ul><p><img src="'+o+'" alt="alt text"></p><p>总结：</p><p>vite之所以快是应为他没有打包过程只有编译，开发服务器在用到那个模块后才会编译那个模块</p><h2 id="vite-webpack" tabindex="-1">vite &amp; webpack <a class="header-anchor" href="#vite-webpack" aria-label="Permalink to &quot;vite &amp; webpack&quot;">​</a></h2><p>webpack会先打包，然后启动开发服务器，请求服务器时直接给予打包结果。</p><p>而vite是直接启动开发服务器，请求那个模块再对该模块进行实时编译。</p><p>由于现代浏览器本身就支持ES Module，会自动向依赖的Module发出请求。vite充分利用这一点，将开发环境下的模块文件，就作为浏览器要执行的文件，而不是像webpack那样进行打包合并。</p><p>由于vite在启动时不需要打包，也就意味着不需要分析模块依赖、不需要编译，因此启动速度非常快。</p><p>当浏览器请求某个模块时，再根据需要对模块内容进行编译。这种按需动态编译的方式，极大的缩减了编译时间，项目越复杂，模块越多，vite的优势越明显。</p><p>在HMR（热替换）方面，当改动一个模块后，仅需要让浏览器重新请求该模块即可，不像webpack那样需要把该模块的相关依赖模块全部编译一次，效率更高。</p><p>当需要打包到生产环境时，vite使用传统的rollup进行打包，因此，vite的主要优势是在开发阶段。另外，由于vite利用的是ES Module，因此代码中不可以使用CommonJS</p>',20)]))}const u=a(c,[["render",r]]);export{v as __pageData,u as default};
